PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry tanh_f32(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .s32 n_elts
)
{
    .reg .pred  %p_done, %p_vec16, %p1, %p2, %p3, %p4, %p5, %p6;
    .reg .s32   %r_tid, %r_bid, %r_bdim, %r_gdim, %idx, %stride, %iter, %base, %tmp, %n, %nrem;
    .reg .u64   %in, %out, %off, %addr_in, %addr_out, %addr0, %addr1;
    .reg .f32   %x0, %x1, %x2, %x3, %y0, %y1, %y2, %y3;
    .reg .f32   %x, %y;
    // Load parameters
    ld.param.u64 %in,  [in_ptr];
    ld.param.u64 %out, [out_ptr];
    ld.param.s32 %n,   [n_elts];
    // Compute thread/block/grid info
    mov.u32  %r_tid,  %tid.x;
    mov.u32  %r_bid,  %ctaid.x;
    mov.u32  %r_bdim, %ntid.x;
    mov.u32  %r_gdim, %nctaid.x;
    // Linear thread index
    mad.lo.s32 %idx, %r_bid, %r_bdim, %r_tid;
    // Stride = gridDim.x * blockDim.x
    mul.lo.s32 %stride, %r_gdim, %r_bdim;
    // Initialize iterator
    mov.s32 %iter, %idx;
LOOP:
    // Base element index = iter * 16 (unroll by 4x v4)
    shl.b32 %base, %iter, 4;
    // If base >= n, exit
    setp.ge.s32 %p_done, %base, %n;
    @%p_done bra DONE;
    // Byte offset and base addresses (off = iter * 64 bytes)
    mul.wide.s32 %off, %iter, 64;
    add.u64 %addr_in,  %in,  %off;
    add.u64 %addr_out, %out, %off;
    // If we have at least 16 elements remaining, take the 4x v4 vectorized path
    add.s32 %tmp, %base, 15;
    setp.lt.s32 %p_vec16, %tmp, %n;
    @%p_vec16 bra VEC4_PATH;
    // Tail/general path (0-15 remaining elements)
    sub.s32 %nrem, %n, %base;
    // If we have at least 8 elements, do two v4 first
    setp.gt.s32 %p1, %nrem, 7;
    @!%p1 bra TAIL_LT8;
    // First 8 elements: two v4 loads/stores at +0B and +16B
    ld.global.cs.v4.f32 { %x0, %x1, %x2, %x3 }, [%addr_in];
    tanh.approx.f32 %y0, %x0;
    tanh.approx.f32 %y1, %x1;
    tanh.approx.f32 %y2, %x2;
    tanh.approx.f32 %y3, %x3;
    st.global.cs.v4.f32 [%addr_out], { %y0, %y1, %y2, %y3 };
    add.u64 %addr0, %addr_in, 16;
    add.u64 %addr1, %addr_out, 16;
    ld.global.cs.v4.f32 { %x0, %x1, %x2, %x3 }, [%addr0];
    tanh.approx.f32 %y0, %x0;
    tanh.approx.f32 %y1, %x1;
    tanh.approx.f32 %y2, %x2;
    tanh.approx.f32 %y3, %x3;
    st.global.cs.v4.f32 [%addr1], { %y0, %y1, %y2, %y3 };
    // Handle remaining 0-7 elements (elements 8..15)
    sub.s32 %nrem, %nrem, 8;
    add.u64 %addr0, %addr_in, 32;
    add.u64 %addr1, %addr_out, 32;
    // If we have at least 4 more, do one v4 at +32B
    setp.gt.s32 %p2, %nrem, 3;
    @!%p2 bra TAIL_SCALAR_GE8;
    ld.global.cs.v4.f32 { %x0, %x1, %x2, %x3 }, [%addr0];
    tanh.approx.f32 %y0, %x0;
    tanh.approx.f32 %y1, %x1;
    tanh.approx.f32 %y2, %x2;
    tanh.approx.f32 %y3, %x3;
    st.global.cs.v4.f32 [%addr1], { %y0, %y1, %y2, %y3 };
    sub.s32 %nrem, %nrem, 4;
    add.u64 %addr0, %addr0, 16;
    add.u64 %addr1, %addr1, 16;
TAIL_SCALAR_GE8:
    // Scalar tail for remaining 1-3 elements starting at current addr0
    setp.gt.s32 %p3, %nrem, 0;
    @!%p3 bra INC;
    ld.global.cs.f32 %x, [%addr0];
    tanh.approx.f32 %y, %x;
    st.global.cs.f32 [%addr1], %y;
    setp.gt.s32 %p4, %nrem, 1;
    @!%p4 bra INC;
    add.u64 %addr0, %addr0, 4;
    add.u64 %addr1, %addr1, 4;
    ld.global.cs.f32 %x, [%addr0];
    tanh.approx.f32 %y, %x;
    st.global.cs.f32 [%addr1], %y;
    setp.gt.s32 %p5, %nrem, 2;
    @!%p5 bra INC;
    add.u64 %addr0, %addr0, 4;
    add.u64 %addr1, %addr1, 4;
    ld.global.cs.f32 %x, [%addr0];
    tanh.approx.f32 %y, %x;
    st.global.cs.f32 [%addr1], %y;
    bra INC;
TAIL_LT8:
    // 1-7 remaining elements
    // If we have at least 4 elements, do one v4 first at +0B
    setp.gt.s32 %p2, %nrem, 3;
    @!%p2 bra TAIL_LT4;
    ld.global.cs.v4.f32 { %x0, %x1, %x2, %x3 }, [%addr_in];
    tanh.approx.f32 %y0, %x0;
    tanh.approx.f32 %y1, %x1;
    tanh.approx.f32 %y2, %x2;
    tanh.approx.f32 %y3, %x3;
    st.global.cs.v4.f32 [%addr_out], { %y0, %y1, %y2, %y3 };
    sub.s32 %nrem, %nrem, 4;
    add.u64 %addr0, %addr_in, 16;
    add.u64 %addr1, %addr_out, 16;
    // Handle remaining 1-3 elements starting at +16B
    setp.gt.s32 %p3, %nrem, 0;
    @!%p3 bra INC;
    ld.global.cs.f32 %x, [%addr0];
    tanh.approx.f32 %y, %x;
    st.global.cs.f32 [%addr1], %y;
    setp.gt.s32 %p4, %nrem, 1;
    @!%p4 bra INC;
    add.u64 %addr0, %addr0, 4;
    add.u64 %addr1, %addr1, 4;
    ld.global.cs.f32 %x, [%addr0];
    tanh.approx.f32 %y, %x;
    st.global.cs.f32 [%addr1], %y;
    setp.gt.s32 %p5, %nrem, 2;
    @!%p5 bra INC;
    add.u64 %addr0, %addr0, 4;
    add.u64 %addr1, %addr1, 4;
    ld.global.cs.f32 %x, [%addr0];
    tanh.approx.f32 %y, %x;
    st.global.cs.f32 [%addr1], %y;
    bra INC;
TAIL_LT4:
    // Scalar tail for 1-3 remaining elements at base +0B
    setp.gt.s32 %p1, %nrem, 0;
    @!%p1 bra INC;
    ld.global.cs.f32 %x, [%addr_in];
    tanh.approx.f32 %y, %x;
    st.global.cs.f32 [%addr_out], %y;
    setp.gt.s32 %p2, %nrem, 1;
    @!%p2 bra INC;
    add.u64 %addr0, %addr_in, 4;
    add.u64 %addr1, %addr_out, 4;
    ld.global.cs.f32 %x, [%addr0];
    tanh.approx.f32 %y, %x;
    st.global.cs.f32 [%addr1], %y;
    setp.gt.s32 %p3, %nrem, 2;
    @!%p3 bra INC;
    add.u64 %addr0, %addr_in, 8;
    add.u64 %addr1, %addr_out, 8;
    ld.global.cs.f32 %x, [%addr0];
    tanh.approx.f32 %y, %x;
    st.global.cs.f32 [%addr1], %y;
    bra INC;
VEC4_PATH:
    // Four consecutive vectorized v4 loads/stores (16 elements total)
    ld.global.cs.v4.f32 { %x0, %x1, %x2, %x3 }, [%addr_in];
    tanh.approx.f32 %y0, %x0;
    tanh.approx.f32 %y1, %x1;
    tanh.approx.f32 %y2, %x2;
    tanh.approx.f32 %y3, %x3;
    st.global.cs.v4.f32 [%addr_out], { %y0, %y1, %y2, %y3 };
    add.u64 %addr0, %addr_in, 16;
    add.u64 %addr1, %addr_out, 16;
    ld.global.cs.v4.f32 { %x0, %x1, %x2, %x3 }, [%addr0];
    tanh.approx.f32 %y0, %x0;
    tanh.approx.f32 %y1, %x1;
    tanh.approx.f32 %y2, %x2;
    tanh.approx.f32 %y3, %x3;
    st.global.cs.v4.f32 [%addr1], { %y0, %y1, %y2, %y3 };
    add.u64 %addr0, %addr_in, 32;
    add.u64 %addr1, %addr_out, 32;
    ld.global.cs.v4.f32 { %x0, %x1, %x2, %x3 }, [%addr0];
    tanh.approx.f32 %y0, %x0;
    tanh.approx.f32 %y1, %x1;
    tanh.approx.f32 %y2, %x2;
    tanh.approx.f32 %y3, %x3;
    st.global.cs.v4.f32 [%addr1], { %y0, %y1, %y2, %y3 };
    add.u64 %addr0, %addr_in, 48;
    add.u64 %addr1, %addr_out, 48;
    ld.global.cs.v4.f32 { %x0, %x1, %x2, %x3 }, [%addr0];
    tanh.approx.f32 %y0, %x0;
    tanh.approx.f32 %y1, %x1;
    tanh.approx.f32 %y2, %x2;
    tanh.approx.f32 %y3, %x3;
    st.global.cs.v4.f32 [%addr1], { %y0, %y1, %y2, %y3 };
INC:
