    def __init__(self):
        super().__init__()
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("ModelNew requires CUDA tensor input.")
        if x.dtype != torch.float32:
            raise RuntimeError("ModelNew supports only float32 tensors.")
        if not x.is_contiguous():
            raise RuntimeError("ModelNew requires contiguous input tensor.")
        n = x.numel()
        y = torch.empty(x.shape, dtype=x.dtype, device=x.device)
        module = _get_ptx_module()
        threads = 256
        n_vec = (n + 3) // 4
        n_groups = (n + 15) // 16
        blocks = (n_groups + threads - 1) // threads
        module.launch(
            "tanh_f32",
            grid=(blocks, 1, 1),
            block=(threads, 1, 1),
            arguments=[x, y, i32(n)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

